  BuildContext context,
  Achievement achievement,
) {
  final l10n = gameL10n(context);
  final streak = RegExp(r'^streak_(\d+)$').firstMatch(achievement.id);
  if (streak != null) {
    final days = streak[1]!;
    return (
      title: days == '365'
          ? l10n.achLocYearStreakTitle
          : l10n.achLocStreakTitle(days),
      description: l10n.achLocStreakDescription(days),
    );
  }
  final text = switch (achievement.id) {
    'first_quiz' => (
      l10n.achLocFirstQuizTitle,
      l10n.achLocFirstQuizDescription,
    ),
    'quiz_10' => (l10n.achLocQuiz10Title, l10n.achLocQuiz10Description),
    'points_1000' => (
      l10n.achLocPoints1000Title,
      l10n.achLocPoints1000Description,
    ),
    'perfect_score' => (
      l10n.achLocPerfectScoreTitle,
      l10n.achLocPerfectScoreDescription,
    ),
    'quiz_25' => (l10n.achLocQuiz25Title, l10n.achLocQuiz25Description),
    'quiz_50' => (l10n.achLocQuiz50Title, l10n.achLocQuiz50Description),
    'quiz_100' => (l10n.achLocQuiz100Title, l10n.achLocQuiz100Description),
    'quiz_250' => (l10n.achLocQuiz250Title, l10n.achLocQuiz250Description),
    'points_5000' => (
      l10n.achLocPoints5000Title,
      l10n.achLocPoints5000Description,
    ),
    'points_10000' => (
      l10n.achLocPoints10000Title,
      l10n.achLocPoints10000Description,
    ),
    'points_50000' => (
      l10n.achLocPoints50000Title,
      l10n.achLocPoints50000Description,
    ),
    'points_100000' => (
      l10n.achLocPoints100000Title,
      l10n.achLocPoints100000Description,
    ),
    'daily_1' => (l10n.achLocDaily1Title, l10n.achLocDaily1Description),
    'daily_7' => (l10n.achLocDaily7Title, l10n.achLocDaily7Description),
    'daily_30' => (l10n.achLocDaily30Title, l10n.achLocDaily30Description),
    'sets_5' => (l10n.achLocSets5Title, l10n.achLocSets5Description),
    'sets_25' => (l10n.achLocSets25Title, l10n.achLocSets25Description),
    'sets_50' => (l10n.achLocSets50Title, l10n.achLocSets50Description),
    'sets_100' => (l10n.achLocSets100Title, l10n.achLocSets100Description),
    'cert_1' => (l10n.achLocCert1Title, l10n.achLocCert1Description),
    'cert_5' => (l10n.achLocCert5Title, l10n.achLocCert5Description),
    'cert_21' => (l10n.achLocCert21Title, l10n.achLocCert21Description),
