String? themeFreePeriodText(BuildContext context, AppThemeInfo theme) {
  final period = theme.annualFreePeriod;
  if (period == null) return null;
  final l10n = gameL10n(context);
  return switch (period) {
    AnnualThemeFreePeriod.valentinesWeek => l10n.achLocThemeFreeValentinesWeek,
    AnnualThemeFreePeriod.dqSpecialWeek => l10n.achLocThemeFreeDqSpecialWeek,
  };
}
